package boardgame

// StateVisibility describes trustworthy facets of game and player properties
// in a viewer snapshot. It is generated by the same policy interpretation used
// for declarative legality, never persisted, and contains no property values.
// Dynamic component and custom computed properties are deliberately excluded.
type StateVisibility struct {
	Game    map[string][]string
	Players []map[string][]string
}

var stateVisibilityFacets = []LegalFacet{
	LegalFacetValues, LegalFacetCount, LegalFacetOccupancy,
	LegalFacetOrder, LegalFacetNonEmpty,
}

func propertyVisibility(reader PropertyReader, policies subStateSanitizationTransformation) map[string][]string {
	result := make(map[string][]string, len(reader.Props()))
	for name := range reader.Props() {
		facets := make([]string, 0, len(stateVisibilityFacets))
		for _, facet := range stateVisibilityFacets {
			if facetSurvives(legalPolicyForProp(policies, name), facet) {
				facets = append(facets, visibilityFacetName(facet))
			}
		}
		result[name] = facets
	}
	return result
}

func (s *state) visibleFacets(transformation *sanitizationTransformation) *StateVisibility {
	if transformation == nil {
		transformation = &sanitizationTransformation{Players: make([]subStateSanitizationTransformation, len(s.playerStates))}
	}
	result := &StateVisibility{
		Game:    propertyVisibility(s.gameState.Reader(), transformation.Game),
		Players: make([]map[string][]string, len(s.playerStates)),
	}
	for i, player := range s.playerStates {
		result.Players[i] = propertyVisibility(player.Reader(), transformation.Players[i])
	}
	// Sanitizing an already restricted copy cannot restore knowledge. Copies
	// share only immutable metadata; this intersection allocates new slices.
	if s.sanitized {
		intersect := func(props map[string][]string, previous map[string][]string) {
			for name, facets := range props {
				kept := facets[:0]
				for _, facet := range facets {
					if containsVisibilityFacet(previous[name], facet) {
						kept = append(kept, facet)
					}
				}
				props[name] = kept
			}
		}
		var previousGame map[string][]string
		if s.visibility != nil {
			previousGame = s.visibility.Game
		}
		intersect(result.Game, previousGame)
		for i, props := range result.Players {
			var previous map[string][]string
			if s.visibility != nil && i < len(s.visibility.Players) {
				previous = s.visibility.Players[i]
			}
			intersect(props, previous)
		}
	}
	return result
}

func containsVisibilityFacet(facets []string, facet string) bool {
	for _, candidate := range facets {
		if candidate == facet {
			return true
		}
	}
	return false
}

// PropertyFacetAvailable reports whether a property on this particular state
// copy retains the requested facet. Use it for framework-derived presentation
// values so hidden enum defaults never turn into plausible role/team labels.
// Unknown properties, unsupported groups, and restricted copies without
// metadata fail closed. Authoritative unsanitized state retains every facet.
func PropertyFacetAvailable(subState ImmutableSubState, property string, facet LegalFacet) bool {
	if subState == nil || subState.ImmutableState() == nil {
		return false
	}
	if _, exists := subState.Reader().Props()[property]; !exists {
		return false
	}
	s, ok := subState.ImmutableState().(*state)
	if !ok {
		return false
	}
	if !s.sanitized {
		return facetSurvives(PolicyVisible, facet)
	}
	if s.visibility == nil {
		return false
	}
	ref := subState.StatePropertyRef()
	switch ref.Group {
	case StateGroupGame:
		return containsVisibilityFacet(s.visibility.Game[property], visibilityFacetName(facet))
	case StateGroupPlayer:
		if ref.PlayerIndex >= 0 && int(ref.PlayerIndex) < len(s.visibility.Players) {
			return containsVisibilityFacet(s.visibility.Players[ref.PlayerIndex][property], visibilityFacetName(facet))
		}
	}
	return false
}

// Names are the wire spelling of the existing facet vocabulary, not policies.
func visibilityFacetName(facet LegalFacet) string {
	switch facet {
	case LegalFacetValues:
		return "values"
	case LegalFacetCount:
		return "count"
	case LegalFacetOccupancy:
		return "occupancy"
	case LegalFacetOrder:
		return "order"
	case LegalFacetNonEmpty:
		return "nonempty"
	default:
		return ""
	}
}

// viewerStateJSON keeps viewer metadata out of durable state records and plain
// state marshaling used by existing replay tools.
type viewerStateJSON struct{ state *state }

func (v viewerStateJSON) MarshalJSON() ([]byte, error) {
	return v.state.customMarshalJSON(true, false, true)
}

func stateJSONForViewer(st ImmutableState) interface{} {
	return viewerStateJSON{st.(*state)}
}
